local LadderStruggleMainDailyReward = Class("LadderStruggleMainDailyReward")

------------ lifeCycle ------------
function LadderStruggleMainDailyReward:Awake()
    self:CleanProperties()
end

function LadderStruggleMainDailyReward:OnDestroy()
    self:CleanProperties()
    self.controller = nil
    self = nil
end
------------ lifeCycle ------------

function LadderStruggleMainDailyReward:CleanProperties()
    self.curBattleNum = nil
    self.alreadyGetReward = nil
    self.systemName = nil
    self.component = nil
end

function LadderStruggleMainDailyReward:InitComponent(systemName)
    self:SetSystem(systemName)
    local param1 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 10)
    local param2 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 11)
    NeedBattleNum = checkInt(param1.num)
    GoodsGroupId = checkInt(param2.num)

    self.Animation_Root.playAutomatically = false   -- 阻止自动播放，不然会覆盖先播放的loop动画
end

function LadderStruggleMainDailyReward:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

--- 更新战斗次数
---@param num any
function LadderStruggleMainDailyReward:UpdateBattleNum(num)
    self.curBattleNum = math.min(num, NeedBattleNum)
    self.Txt_Process.text = string.format("%d/%d", self.curBattleNum, NeedBattleNum)
end

--- 增加战斗次数
---@param count any
function LadderStruggleMainDailyReward:AddBattleNum(count)
    local newNum = self.curBattleNum + count
    self:UpdateBattleNum(newNum)
end

--- 设置按钮状态
---@param state any
function LadderStruggleMainDailyReward:SetButtonState(state)
    if state == ButtonState.Lock then
    elseif state == ButtonState.Can then
        local bool = self.Animation_Root:Play(BtnLoopAnim)
    elseif state == ButtonState.Already then
        KTool.SetActive(self.Img_Complete, true)
        self.Img_Reward.color = CS.Engine.Lib.XLuaUtils.HexToColor(AlreadyColor)
    end
    SetButtonAction(self.Btn_Reward, Bind(self, self.OnRewardBtnClick, state))
    GameUtils.SetRedPointNum(self.component.redPointNameDailyReward, state == ButtonState.Can and 1 or 0)
end

function LadderStruggleMainDailyReward:OnRewardBtnClick(state)
    if state == ButtonState.Lock then
        local rewards = self:GetPreviewReward()
        GameUtils.ShowCommonTipsBoardRewardPreview(self.Btn_Reward.gameObject, rewards, localize('胜利宝箱:'), false, true)
    elseif state == ButtonState.Can then
        -- 领取奖励
        GameUtils.CommonDrawRewards(self.component.InterfaceBattleReward, nil, {{id = self.component.UIMainDialog}})
    elseif state == ButtonState.Already then
        GameUtils.Toast(AlreadyGetTips)
    end
end

--- 领奖
function LadderStruggleMainDailyReward:GetPreviewReward()
    local rewards = {}
    for _, vo in ipairs(GoodsUtils.GetGoodsGroupVos(GoodsGroupId)) do
        table.insert(rewards, {goodsId = vo.reward, num = vo.minNum, weight = vo.weight})
    end
    return rewards
end

return LadderStruggleMainDailyReward